function today(): string { const date = new Date(); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
function minimumDate(): string { const date = new Date(); date.setFullYear(date.getFullYear() - 5); return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`; }
function shortDate(value: string): string { const [year, month, day] = value.slice(0, 10).split('-'); return `${day}/${month}/${year}`; }
function longDate(value: string): string { const [year, month, day] = value.slice(0, 10).split('-'); return `${day} ${months[Number(month) - 1]} ${year}`; }
function dateTime(value: string): string { const date = new Date(value); return `${date.toLocaleDateString('id-ID', { day: '2-digit', month: 'long', year: 'numeric' })}, ${date.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' })}`; }
function goTo(path: string): void { window.history.pushState({}, '', path); window.dispatchEvent(new PopStateEvent('popstate')); }
function initials(name: string): string { return name.split(' ').filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'BS'; }
function normalizeSpaces(value: string): string { return value.trim().replace(/\s+/g, ' '); }
function isFutureDate(value: string): boolean { return Boolean(value) && value > today(); }
function isConnectionError(error: unknown): boolean { const message = error instanceof Error ? error.message.toLowerCase() : typeof error === 'object' && error !== null && 'message' in error && typeof error.message === 'string' ? error.message.toLowerCase() : ''; return message.includes('fetch') || message.includes('network') || message.includes('connection') || message.includes('timeout'); }
function safeExcelText(value: string): string { return /^[=+\-@]/.test(value) ? `'${value}` : value; }
function friendlySaveError(error: { code?: string; message?: string } | null): FieldErrors { const message = error?.message?.toLowerCase() ?? ''; if (error?.code === '23505') return { nomor_surat: 'Nomor surat sudah terdaftar' }; if (isConnectionError(error)) return { general: 'Koneksi bermasalah, silakan coba lagi' }; if (message.includes('tanggal surat maksimal 5 tahun')) return { tanggal_surat: 'Tanggal surat maksimal 5 tahun ke belakang' }; if (message.includes('surat_nomor_valid')) return { nomor_surat: 'Nomor surat maksimal 100 karakter' }; if (message.includes('surat_perihal_valid')) return { perihal: 'Perihal maksimal 300 karakter' }; return { general: 'Data tidak valid, periksa kembali isian Anda' }; }

function useDebounced<T>(value: T, delay: number): T {
  const [debounced, setDebounced] = useState<T>(value);
  useEffect(() => {
    const timer = setTimeout(() => setDebounced(value), delay);
    return (): void => clearTimeout(timer);
  }, [value, delay]);
  return debounced;
}

function useCopied(duration = 2000): [boolean, () => void] {
  const [copied, setCopied] = useState(false);
  const timer = useRef<number | null>(null);
  const trigger = useCallback((): void => {
    setCopied(true);
    if (timer.current) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setCopied(false), duration);
  }, [duration]);
  useEffect(() => (): void => { if (timer.current) window.clearTimeout(timer.current); }, []);
  return [copied, trigger];
}

function useClickOutside<T extends HTMLElement>(onOutside: () => void): React.RefObject<T> {
  const ref = useRef<T>(null);
  useEffect(() => {
    function handler(event: MouseEvent): void { if (ref.current && !ref.current.contains(event.target as Node)) onOutside(); }
    document.addEventListener('mousedown', handler);
    return (): void => document.removeEventListener('mousedown', handler);
  }, [onOutside]);
  return ref;
}

async function processImageFile(file: File): Promise<Blob> {
  const img = new Image();
  const url = URL.createObjectURL(file);
  try {
    await new Promise<void>((resolve, reject) => { img.onload = (): void => resolve(); img.onerror = (): void => reject(new Error('load')); img.src = url; });
    const sourceSize = Math.min(img.naturalWidth, img.naturalHeight);
    const sx = (img.naturalWidth - sourceSize) / 2;
    const sy = (img.naturalHeight - sourceSize) / 2;
    const canvas = document.createElement('canvas');
    canvas.width = Math.min(512, sourceSize);
    canvas.height = canvas.width;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('canvas');
    ctx.drawImage(img, sx, sy, sourceSize, sourceSize, 0, 0, canvas.width, canvas.height);
    const blob = await new Promise<Blob>((resolve, reject) => { canvas.toBlob((b) => b ? resolve(b) : reject(new Error('blob')), 'image/jpeg', 0.85); });
    return blob;
  } finally { URL.revokeObjectURL(url); }
}

const ToastContext = { current: null as null | ((message: string, tone?: ToastTone) => void) };
function useToast(): (message: string, tone?: ToastTone) => void {
  return useCallback((message: string, tone?: ToastTone): void => { ToastContext.current?.(message, tone); }, []);
}

function ToastHost(): ReactNode {
  const [toasts, setToasts] = useState<ToastItem[]>([]);
  const push = useCallback((message: string, tone: ToastTone = 'success'): void => {
    const id = Date.now() + Math.random();
    setToasts((current) => [...current, { id, message, tone }]);
    window.setTimeout(() => setToasts((current) => current.filter((t) => t.id !== id)), 3000);
  }, []);
  useEffect(() => { ToastContext.current = push; return (): void => { ToastContext.current = null; }; }, [push]);
  const remove = useCallback((id: number): void => setToasts((current) => current.filter((t) => t.id !== id)), []);
  const toneStyles: Record<ToastTone, string> = { success: 'bg-[var(--primary)] text-white', error: 'bg-red-600 text-white', info: 'bg-[var(--ink)] text-white' };
  return <div className="fixed right-4 top-4 z-50 flex flex-col gap-2.5 sm:right-6 sm:top-6">{toasts.map((toast) => <div key={toast.id} className={`animate-toast-in flex items-center gap-2.5 rounded-xl px-4 py-3 shadow-lg ${toneStyles[toast.tone]}`}><span className="flex h-5 w-5 items-center justify-center"><Check size={15} /></span><span className="text-sm font-semibold">{toast.message}</span><button onClick={() => remove(toast.id)} className="ml-1 rounded p-0.5 opacity-80 hover:opacity-100" aria-label="Tutup"><X size={14} /></button></div>)}</div>;
}

