function Avatar({ name, path, className }: { name: string; path: string | null; className: string }): ReactNode {
  const [url, setUrl] = useState<string | null>(null);
  const [failed, setFailed] = useState(false);
  useEffect(() => {
    if (!path) { setUrl(null); setFailed(false); return; }
    let active = true;
    supabase.storage.from('avatars').createSignedUrl(path, 3600).then(({ data }) => {
      if (!active) return;
      if (data?.signedUrl) { setUrl(data.signedUrl); setFailed(false); } else setFailed(true);
    }).catch(() => { if (active) setFailed(true); });
    return (): void => { active = false; };
  }, [path]);
  if (url && !failed) return <img src={url} alt={name} onError={() => setFailed(true)} className={`rounded-full object-cover ${className}`} />;
  return <span className={`flex items-center justify-center rounded-full bg-[#dff4f2] font-bold text-[var(--primary)] ${className}`}>{initials(name)}</span>;
}

class AppErrorBoundary extends Component<{ children: ReactNode }, ErrorBoundaryState> {
  state: ErrorBoundaryState = { hasError: false };
  static getDerivedStateFromError(): ErrorBoundaryState { return { hasError: true }; }
  componentDidCatch(): void { this.setState({ hasError: true }); }
  render(): ReactNode { if (!this.state.hasError) return this.props.children; return <main className="flex min-h-screen items-center justify-center bg-[var(--page)] px-5"><Card><div className="max-w-md text-center"><h1 className="text-xl font-bold text-[var(--ink)]">Terjadi kesalahan. Muat ulang halaman.</h1><button onClick={() => window.location.reload()} className="mt-5 h-11 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white">Muat Ulang</button></div></Card></main>; }
}

