function CopyButton({ text, onCopied, className }: { text: string; onCopied?: () => void; className?: string }): ReactNode { const [copied, trigger] = useCopied(2000); async function copy(): Promise<void> { try { await navigator.clipboard.writeText(text); trigger(); onCopied?.(); } catch { /* ignore */ } } return <button onClick={() => void copy()} className={className} aria-label="Salin">{copied ? <Check size={17} /> : <Copy size={17} />}</button>; }

function LoginPage({ onLogin, sessionMessage }: { onLogin: (session: Session) => Promise<void>; sessionMessage: string }): ReactNode { const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const registered = new URLSearchParams(window.location.search).get('registered') === '1'; async function submit(event: FormEvent): Promise<void> { event.preventDefault(); setBusy(true); setError(''); const { data, error: signInError } = await supabase.auth.signInWithPassword({ email: email.trim().toLowerCase(), password }); setBusy(false); if (signInError || !data.session) { setError(isConnectionError(signInError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Email atau password salah'); return; } await onLogin(data.session); } return <AuthLayout><div className="mb-7 text-center"><div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-[#dff4f2] text-[var(--primary)]"><LockKeyhole size={22} /></div><h1 className="text-2xl font-bold text-[var(--ink)]">Login</h1><p className="mt-2 text-sm text-slate-500">Masuk untuk mengakses sistem</p></div>{sessionMessage && <p className="mb-4 rounded-lg bg-amber-50 px-3 py-2.5 text-sm text-amber-800">{sessionMessage}</p>}{registered && <p className="mb-4 rounded-lg bg-emerald-50 px-3 py-2.5 text-sm text-emerald-700">Akun berhasil dibuat, silakan masuk</p>}<form onSubmit={(event) => void submit(event)} className="space-y-4"><InputField label="Email" type="email" value={email} onChange={setEmail} placeholder="nama@contoh.com" autoComplete="email" /><PasswordField label="Password" value={password} onChange={setPassword} autoComplete="current-password" />{error && <p className="rounded-lg bg-red-50 px-3 py-2.5 text-sm text-red-700">{error}</p>}<button disabled={busy} className="h-11 w-full rounded-lg bg-[var(--primary)] text-sm font-semibold text-white hover:bg-[var(--primary-dark)] disabled:cursor-not-allowed disabled:opacity-60">{busy ? 'Memproses...' : 'Masuk'}</button></form><button onClick={() => goTo('/daftar')} className="mt-5 w-full text-center text-sm font-semibold text-[var(--primary)] hover:underline">Daftar dengan kode pendaftaran</button><p className="mt-3 text-center text-xs text-slate-400">Lupa password? Hubungi super admin</p></AuthLayout>; }
function RegisterPage(): ReactNode { const [values, setValues] = useState({ fullName: '', email: '', password: '', confirmation: '', token: '' }); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const update = (key: keyof typeof values, value: string): void => setValues((current) => ({ ...current, [key]: value })); async function submit(event: FormEvent): Promise<void> { event.preventDefault(); setError(''); const fullName = values.fullName.trim(); const email = values.email.trim().toLowerCase(); if (!fullName) { setError('Nama lengkap wajib diisi'); return; } if (values.password !== values.confirmation) { setError('Konfirmasi password tidak sama'); return; } setBusy(true); const { data, error: invokeError } = await supabase.functions.invoke('register-with-token', { body: { full_name: fullName, email, password: values.password, token: values.token.trim() } }); let responseError = typeof data?.error === 'string' ? data.error : ''; if (!responseError && invokeError && 'context' in invokeError && invokeError.context instanceof Response) { try { const body = await invokeError.context.clone().json() as { error?: unknown }; if (typeof body.error === 'string') responseError = body.error; } catch { responseError = ''; } } setBusy(false); if (invokeError || responseError) { setError(isConnectionError(invokeError) ? 'Koneksi bermasalah, silakan coba lagi' : responseError || 'Pendaftaran tidak dapat diproses'); return; } goTo('/?registered=1'); } return <AuthLayout><div className="mb-7 text-center"><h1 className="text-2xl font-bold text-[var(--ink)]">Daftar Akun</h1><p className="mt-2 text-sm text-slate-500">Gunakan kode pendaftaran dari super admin</p></div><form onSubmit={(event) => void submit(event)} className="space-y-3.5"><InputField label="Nama lengkap" value={values.fullName} onChange={(value) => update('fullName', value)} placeholder="Nama lengkap" /><InputField label="Email" type="email" value={values.email} onChange={(value) => update('email', value)} placeholder="nama@contoh.com" autoComplete="email" /><PasswordField label="Password" value={values.password} onChange={(value) => update('password', value)} autoComplete="new-password" /><PasswordField label="Konfirmasi password" value={values.confirmation} onChange={(value) => update('confirmation', value)} autoComplete="new-password" /><InputField label="Kode pendaftaran" value={values.token} onChange={(value) => update('token', value)} placeholder="Contoh: K7M2-Q9XP" />{error && <p className="rounded-lg bg-red-50 px-3 py-2.5 text-sm text-red-700">{error}</p>}<button disabled={busy} className="h-11 w-full rounded-lg bg-[var(--primary)] text-sm font-semibold text-white hover:bg-[var(--primary-dark)] disabled:cursor-not-allowed disabled:opacity-60">{busy ? 'Memproses...' : 'Daftar'}</button></form><button onClick={() => goTo('/')} className="mt-5 w-full text-center text-sm font-semibold text-[var(--primary)] hover:underline">Sudah punya akun? Masuk</button></AuthLayout>; }
function ChangePasswordPage({ onComplete }: { onComplete: () => Promise<void> }): ReactNode { const [password, setPassword] = useState(''); const [confirmation, setConfirmation] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); async function submit(event: FormEvent): Promise<void> { event.preventDefault(); if (password.length < 8) { setError('Password minimal 8 karakter'); return; } if (password !== confirmation) { setError('Konfirmasi password tidak sama'); return; } setBusy(true); const { error: updateError } = await supabase.auth.updateUser({ password }); if (updateError) { setError('Password tidak dapat diubah'); setBusy(false); return; } const { error: clearError } = await supabase.rpc('clear_must_change_password'); setBusy(false); if (clearError) { setError('Password berhasil diubah, tetapi proses belum selesai'); return; } await onComplete(); } return <AuthLayout><div className="mb-7 text-center"><div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-[#dff4f2] text-[var(--primary)]"><KeyRound size={22} /></div><h1 className="text-2xl font-bold text-[var(--ink)]">Ganti Password</h1><p className="mt-2 text-sm text-slate-500">Buat password baru sebelum melanjutkan</p></div><form onSubmit={(event) => void submit(event)} className="space-y-4"><PasswordField label="Password baru" value={password} onChange={setPassword} autoComplete="new-password" /><PasswordField label="Konfirmasi password" value={confirmation} onChange={setConfirmation} autoComplete="new-password" />{error && <p className="rounded-lg bg-red-50 px-3 py-2.5 text-sm text-red-700">{error}</p>}<button disabled={busy} className="h-11 w-full rounded-lg bg-[var(--primary)] text-sm font-semibold text-white hover:bg-[var(--primary-dark)] disabled:cursor-not-allowed disabled:opacity-60">{busy ? 'Menyimpan...' : 'Simpan password baru'}</button></form></AuthLayout>; }

