function Dashboard({ profile, onGoData, onGoInput }: { profile: Profile; onGoData: () => void; onGoInput: () => void }): ReactNode {
  const [rows, setRows] = useState<Surat[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selected, setSelected] = useState<Surat | null>(null);
  useEffect(() => { setLoading(true); supabase.from('surat').select('id, nomor_surat, tanggal_surat, perihal, kategori, status, created_by, created_at, updated_at, profiles(full_name)').eq('status', 'aktif').order('created_at', { ascending: false }).then(({ data, error: loadError }) => { if (loadError) setError(isConnectionError(loadError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Data surat tidak dapat dimuat'); else setRows((data ?? []) as unknown as Surat[]); setLoading(false); }); }, []);
  const displayName = profile.full_name || profile.email;
  const dateToday = new Date().toLocaleDateString('id-ID', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
  return <><div className="mb-7 flex flex-col justify-between gap-3 sm:flex-row sm:items-end"><div><PageHeading title="Dashboard" current="Dashboard" /><p className="-mt-5 text-sm text-slate-500">Selamat datang, <span className="font-semibold text-[var(--ink)]">{displayName}</span></p></div><p className="flex items-center gap-2 text-sm text-slate-500"><CalendarDays size={16} className="text-[var(--primary)]" />{dateToday}</p></div>{error && <div className="mb-5"><ErrorNotice message={error} /></div>}<Card className="mt-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-lg font-bold text-[var(--ink)]">Surat Terbaru</h2><p className="mt-1 text-sm text-slate-400">Lima surat aktif terakhir yang dicatat</p></div><button onClick={onGoData} className="text-sm font-semibold text-[var(--primary)] hover:underline">Lihat Semua</button></div><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-sm"><thead className="border-b border-[var(--line)] text-xs uppercase tracking-wide text-slate-400"><tr><th className="pb-3">No. Surat</th><th className="pb-3">Tanggal</th><th className="pb-3">Perihal</th><th className="pb-3">Penginput</th></tr></thead><tbody className="divide-y divide-[var(--line)]">{loading ? Array.from({ length: 4 }, (_, i) => <SkeletonRow key={i} />) : rows.slice(0, 5).map((row) => <tr key={row.id} onClick={() => setSelected(row)} className="cursor-pointer transition hover:bg-slate-50"><td className="py-3.5 font-semibold text-[var(--ink)]">{row.nomor_surat}</td><td className="py-3.5 text-slate-500">{shortDate(row.tanggal_surat)}</td><td className="py-3.5 text-slate-600">{row.perihal}</td><td className="py-3.5 text-slate-500">{row.profiles?.full_name || 'Tanpa nama'}</td></tr>)}</tbody></table>{!loading && rows.length === 0 && <EmptyState title="Belum ada data surat" subtitle="Surat yang Anda input akan muncul di sini" actionLabel="Input Surat" onAction={onGoInput} />}</div></Card>{selected && <Dialog title="Detail Surat" onClose={() => setSelected(null)}><div className="space-y-4"><Detail label="Nomor Surat" value={selected.nomor_surat} /><Detail label="Tanggal" value={longDate(selected.tanggal_surat)} /><Detail label="Perihal" value={selected.perihal} /><Detail label="Kategori" value={kategoriLabel(selected.kategori)} /><Detail label="Penginput" value={selected.profiles?.full_name || 'Tanpa nama'} /><Detail label="Tanggal Input" value={dateTime(selected.created_at)} /><Detail label="Status" value={selected.status === 'aktif' ? 'Aktif' : 'Dibatalkan'} /></div></Dialog>}</>;
}

function SuratForm({ profile, initial, editId, onSaved, onCancel }: { profile: Profile; initial?: SuratFormValue; editId?: string; onSaved: (message: string) => void; onCancel?: () => void }): ReactNode {
  const [form, setForm] = useState<SuratFormValue>(initial ?? { nomor_surat: '', tanggal_surat: today(), perihal: '', kategori: 'Lainnya' });
  const [errors, setErrors] = useState<FieldErrors>({});
  const [busy, setBusy] = useState(false);
  const nomorRef = useRef<HTMLInputElement>(null);
  useEffect(() => { if (!editId) nomorRef.current?.focus(); }, [editId]);
  function validate(key: keyof SuratFormValue, value: string): string | undefined {
    if (key === 'nomor_surat') { const v = normalizeSpaces(value); if (!v) return 'Nomor surat wajib diisi'; }
    if (key === 'perihal') { const v = normalizeSpaces(value); if (!v) return 'Perihal wajib diisi'; }
    if (key === 'tanggal_surat') { if (!value) return 'Tanggal surat wajib diisi'; if (value < minimumDate()) return 'Tanggal surat maksimal 5 tahun ke belakang'; }
    if (key === 'kategori') { if (!categories.includes(value as Kategori)) return 'Kategori tidak valid'; }
    return undefined;
  }
  const set = (key: keyof SuratFormValue, value: string): void => {
    setForm((current) => ({ ...current, [key]: value }));
    setErrors((current) => ({ ...current, [key]: validate(key, value), general: undefined }));
  };
  async function submit(event: FormEvent): Promise<void> {
    event.preventDefault();
    const values = { nomor_surat: normalizeSpaces(form.nomor_surat), tanggal_surat: form.tanggal_surat, perihal: normalizeSpaces(form.perihal), kategori: form.kategori };
    const nextErrors: FieldErrors = { nomor_surat: validate('nomor_surat', values.nomor_surat), perihal: validate('perihal', values.perihal), tanggal_surat: validate('tanggal_surat', values.tanggal_surat), kategori: validate('kategori', values.kategori) };
    if (nextErrors.nomor_surat || nextErrors.perihal || nextErrors.tanggal_surat || nextErrors.kategori) { setErrors(nextErrors); return; }
    setForm(values); setErrors({}); setBusy(true);
    const query = editId ? supabase.from('surat').update(values).eq('id', editId) : supabase.from('surat').insert({ ...values, created_by: profile.id });
    const { error: saveError } = await query; setBusy(false);
    if (saveError) { setErrors(friendlySaveError(saveError)); return; }
    onSaved(editId ? 'Surat berhasil diperbarui' : 'Surat berhasil disimpan');
  }
  const future = isFutureDate(form.tanggal_surat);
  return <form onSubmit={(event) => void submit(event)} className="grid gap-7 lg:grid-cols-[1.15fr_.85fr]"><div className="space-y-5"><label className="block text-sm font-semibold">Tanggal Surat<input type="date" min={minimumDate()} value={form.tanggal_surat} onChange={(event) => set('tanggal_surat', event.target.value)} required className="mt-2 h-11 w-full rounded-lg border border-[var(--line)] bg-[#fbfcfc] px-3.5 text-sm outline-none focus:border-[var(--primary)]" />{errors.tanggal_surat && <span className="mt-2 block text-sm font-medium text-red-600">{errors.tanggal_surat}</span>}{future && !errors.tanggal_surat && <span className="mt-2 block text-sm font-medium text-amber-700">Tanggal surat berada di masa depan, pastikan sudah benar</span>}</label><label className="block text-sm font-semibold">Nomor Surat<input ref={nomorRef} value={form.nomor_surat} maxLength={100} onChange={(event) => set('nomor_surat', event.target.value)} required placeholder="Masukkan nomor surat" className="mt-2 h-11 w-full rounded-lg border border-[var(--line)] bg-[#fbfcfc] px-3.5 text-sm outline-none focus:border-[var(--primary)]" />{errors.nomor_surat && <span className="mt-2 block text-sm font-medium text-red-600">{errors.nomor_surat}</span>}<span className="mt-1.5 block text-xs font-normal text-slate-400">Nomor surat diisi sesuai nomor yang diberikan oleh pihak BSI.</span></label><label className="block text-sm font-semibold">Kategori<select value={form.kategori} onChange={(event) => set('kategori', event.target.value)} className="mt-2 h-11 w-full rounded-lg border border-[var(--line)] bg-[#fbfcfc] px-3.5 text-sm outline-none focus:border-[var(--primary)]">{categories.map((cat) => <option key={cat} value={cat}>{cat}</option>)}</select>{errors.kategori && <span className="mt-2 block text-sm font-medium text-red-600">{errors.kategori}</span>}<span className="mt-1.5 block text-xs font-normal text-slate-400">Pilih kategori surat untuk memudahkan penyaringan.</span></label><label className="block text-sm font-semibold">Perihal<input value={form.perihal} maxLength={300} onChange={(event) => set('perihal', event.target.value)} required placeholder="Masukkan perihal surat" className="mt-2 h-11 w-full rounded-lg border border-[var(--line)] bg-[#fbfcfc] px-3.5 text-sm outline-none focus:border-[var(--primary)]" />{errors.perihal && <span className="mt-2 block text-sm font-medium text-red-600">{errors.perihal}</span>}</label>{errors.general && <ErrorNotice message={errors.general} />}</div><div className="flex flex-col justify-between"><div><p className="text-sm font-semibold">Penginput</p><div className="mt-2 rounded-lg border border-[var(--line)] bg-[#f4f7f8] px-4 py-3"><p className="text-sm font-semibold text-[var(--ink)]">{profile.full_name || profile.email}</p><p className="mt-1 text-xs text-slate-400">{profile.role === 'super_admin' ? 'Super Admin' : 'Admin'}</p></div></div><div className="mt-8 flex justify-end gap-3"><button type="button" onClick={() => onCancel ? onCancel() : setForm({ nomor_surat: '', tanggal_surat: today(), perihal: '', kategori: 'Lainnya' })} className="h-11 rounded-lg border border-[var(--line)] px-5 text-sm font-semibold text-slate-600 hover:bg-slate-50">Batal</button><button disabled={busy} className="h-11 rounded-lg bg-[var(--primary)] px-6 text-sm font-semibold text-white hover:bg-[var(--primary-dark)] disabled:cursor-not-allowed disabled:opacity-60">{busy ? 'Menyimpan...' : 'Simpan'}</button></div></div></form>;
}
function InputPage({ profile, onGoData }: { profile: Profile; onGoData: () => void }): ReactNode {
  const [saved, setSaved] = useState(false);
  const toast = useToast();
  function handleSaved(message: string): void { setSaved(true); toast(message); window.setTimeout(() => setSaved(false), 1500); }
  function resetForm(): void { setSaved(false); }
  return <><PageHeading title="Input Surat" current="Input Surat" /><Card><div className="grid gap-7 lg:grid-cols-[1.15fr_.85fr]">{saved ? <div className="col-span-full flex flex-col items-center py-10"><div className="animate-scale-in flex h-14 w-14 items-center justify-center rounded-full bg-emerald-100 text-emerald-600"><CheckCheck size={28} /></div><p className="mt-4 text-sm font-semibold text-[var(--ink)]">Surat berhasil disimpan</p><div className="mt-5 flex flex-wrap justify-center gap-3"><button onClick={() => resetForm()} className="h-11 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white hover:bg-[var(--primary-dark)]">Input surat lagi</button><button onClick={onGoData} className="h-11 rounded-lg border border-[var(--line)] px-5 text-sm font-semibold text-slate-600 hover:bg-slate-50">Lihat di Data Surat</button></div></div> : <SuratForm profile={profile} onSaved={handleSaved} />}</div></Card></>;
}

function Dialog({ title, children, onClose, wide = false, dismissible = true, autoFocus = true }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean; dismissible?: boolean; autoFocus?: boolean }): ReactNode {
  const panelRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return (): void => { document.body.style.overflow = previous; };
  }, []);
  useEffect(() => {
    function onKey(event: KeyboardEvent): void { if (event.key === 'Escape' && dismissible) onClose(); }
    document.addEventListener('keydown', onKey);
    return (): void => document.removeEventListener('keydown', onKey);
  }, [onClose, dismissible]);
  useEffect(() => {
    if (!autoFocus) return;
    const timer = setTimeout(() => {
      const panel = panelRef.current;
      if (!panel) return;
      const focusable = panel.querySelector<HTMLElement>('input, select, textarea, button:not([disabled])');
      focusable?.focus();
    }, 50);
    return (): void => clearTimeout(timer);
  }, [autoFocus]);
  function onBackdropClick(event: React.MouseEvent<HTMLDivElement>): void { if (dismissible && event.target === event.currentTarget) onClose(); }
  return createPortal(<div onClick={onBackdropClick} className="fixed inset-0 z-[60] flex items-center justify-center overflow-y-auto bg-[rgba(11,59,71,.42)] px-4 py-8"><div ref={panelRef} className={`animate-scale-in w-full ${wide ? 'max-w-2xl' : 'max-w-lg'} rounded-2xl bg-white p-6 shadow-2xl sm:p-8`}><div className="mb-6 flex items-center justify-between"><h2 className="text-xl font-bold">{title}</h2><button onClick={onClose} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100" aria-label="Tutup"><X size={19} /></button></div>{children}</div></div>, document.body);
}
function Detail({ label, value }: { label: string; value: string }): ReactNode { return <div><p className="text-xs font-semibold uppercase tracking-wide text-slate-400">{label}</p><p className="mt-1 text-sm font-medium text-[var(--ink)]">{value}</p></div>; }

function EmptyState({ title, subtitle, actionLabel, onAction }: { title: string; subtitle: string; actionLabel?: string; onAction?: () => void }): ReactNode { return <div className="flex flex-col items-center py-14"><div className="flex h-16 w-16 items-center justify-center rounded-full bg-[#f0f4f5] text-slate-300"><Inbox size={30} /></div><p className="mt-4 text-sm font-semibold text-[var(--ink)]">{title}</p><p className="mt-1 text-sm text-slate-400">{subtitle}</p>{actionLabel && onAction && <button onClick={onAction} className="mt-5 h-10 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white hover:bg-[var(--primary-dark)]">{actionLabel}</button>}</div>; }

function pageRange(current: number, total: number): (number | 'ellipsis')[] {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
  const pages: (number | 'ellipsis')[] = [1];
  const start = Math.max(2, current - 1);
  const end = Math.min(total - 1, current + 1);
  if (start > 2) pages.push('ellipsis');
  for (let i = start; i <= end; i++) pages.push(i);
  if (end < total - 1) pages.push('ellipsis');
  pages.push(total);
  return pages;
}

function Pagination({ page, count, onChange }: { page: number; count: number; onChange: (page: number) => void }): ReactNode {
  if (count <= 1) return null;
  const pages = pageRange(page, count);
  return <div className="flex items-center gap-1"><button disabled={page === 1} onClick={() => onChange(Math.max(1, page - 1))} className="rounded-lg border border-[var(--line)] p-2 disabled:opacity-40"><ChevronLeft size={16} /></button>{pages.map((item, i) => item === 'ellipsis' ? <span key={`e-${i}`} className="px-1 text-sm text-slate-400">···</span> : <button key={item} onClick={() => onChange(item)} className={`h-8 min-w-8 rounded-lg px-2 text-sm font-semibold ${page === item ? 'bg-[var(--primary)] text-white' : 'text-slate-500 hover:bg-slate-100'}`}>{item}</button>)}<button disabled={page === count} onClick={() => onChange(Math.min(count, page + 1))} className="rounded-lg border border-[var(--line)] p-2 disabled:opacity-40"><ChevronRight size={16} /></button></div>;
}

function SortIcon({ active, dir }: { active: boolean; dir: SortDir }): ReactNode { if (!active) return <ChevronDown size={13} className="text-slate-300" />; return dir === 'asc' ? <ChevronUp size={13} className="text-[var(--primary)]" /> : <ChevronDown size={13} className="text-[var(--primary)]" />; }

function DataPage({ profile }: { profile: Profile }): ReactNode {
  const [rows, setRows] = useState<Surat[]>([]);
  const [loading, setLoading] = useState(true);
  const [draftSearch, setDraftSearch] = useState('');
  const [draftMonth, setDraftMonth] = useState('');
  const [draftYear, setDraftYear] = useState('');
  const [draftKategori, setDraftKategori] = useState('');
  const [draftStartDate, setDraftStartDate] = useState('');
  const [draftEndDate, setDraftEndDate] = useState('');
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [search, setSearch] = useState('');
  const [month, setMonth] = useState('');
  const [year, setYear] = useState('');
  const [kategori, setKategori] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [cancelled, setCancelled] = useState(false);
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<Surat | null>(null);
  const [editing, setEditing] = useState<Surat | null>(null);
  const [confirming, setConfirming] = useState<Surat | null>(null);
  const [error, setError] = useState('');
  const [statusBusy, setStatusBusy] = useState(false);
  const [downloadBusy, setDownloadBusy] = useState(false);
  const [sortKey, setSortKey] = useState<SortKey>('created_at');
  const [sortDir, setSortDir] = useState<SortDir>('desc');
  const toast = useToast();
  const debouncedSearch = useDebounced(draftSearch, 250);
  useEffect(() => { setSearch(debouncedSearch); }, [debouncedSearch]);
  useEffect(() => { setMonth(draftMonth); }, [draftMonth]);
  useEffect(() => { setYear(draftYear); }, [draftYear]);
  useEffect(() => { setKategori(draftKategori); }, [draftKategori]);
  useEffect(() => { setStartDate(draftStartDate); }, [draftStartDate]);
  useEffect(() => { setEndDate(draftEndDate); }, [draftEndDate]);
  async function load(): Promise<void> { setLoading(true); const { data, error: loadError } = await supabase.from('surat').select('id, nomor_surat, tanggal_surat, perihal, kategori, status, created_by, created_at, updated_at, profiles(full_name)').order('created_at', { ascending: false }); if (loadError) setError(isConnectionError(loadError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Data surat tidak dapat dimuat'); else setRows((data ?? []) as unknown as Surat[]); setLoading(false); }
  useEffect(() => { void load(); }, []);
  const years = useMemo(() => [...new Set(rows.map((row) => row.tanggal_surat.slice(0, 4)))].sort((a, b) => Number(b) - Number(a)), [rows]);
  const filtered = useMemo(() => {
    const result = rows.filter((row) => `${row.nomor_surat} ${row.perihal}`.toLowerCase().includes(search.toLowerCase()) && (!month || String(Number(row.tanggal_surat.slice(5, 7))) === month) && (!year || row.tanggal_surat.startsWith(year)) && (!kategori || row.kategori === kategori) && (!startDate || row.tanggal_surat >= startDate) && (!endDate || row.tanggal_surat <= endDate) && (cancelled || row.status === 'aktif'));
    const sorted = [...result].sort((a, b) => {
      let cmp = 0;
      if (sortKey === 'tanggal_surat') cmp = a.tanggal_surat.localeCompare(b.tanggal_surat);
      else if (sortKey === 'created_at') cmp = a.created_at.localeCompare(b.created_at);
      else cmp = String(a[sortKey]).localeCompare(String(b[sortKey]), 'id');
      return sortDir === 'asc' ? cmp : -cmp;
    });
    return sorted;
  }, [rows, search, month, year, kategori, startDate, endDate, cancelled, sortKey, sortDir]);
  const count = Math.max(1, Math.ceil(filtered.length / 10));
  const visible = filtered.slice((page - 1) * 10, page * 10);
  useEffect(() => { setPage(1); }, [search, month, year, kategori, startDate, endDate, cancelled]);
  function toggleSort(key: SortKey): void { if (sortKey === key) setSortDir((d) => d === 'asc' ? 'desc' : 'asc'); else { setSortKey(key); setSortDir('asc'); } }
  async function download(): Promise<void> { setDownloadBusy(true); setError(''); const active: Surat[] = []; let start = 0; while (true) { let query = supabase.from('surat').select('id, nomor_surat, tanggal_surat, perihal, kategori, status, created_by, created_at, updated_at, profiles(full_name)').eq('status', 'aktif').order('tanggal_surat', { ascending: true }).order('created_at', { ascending: true }).range(start, start + 999); if (year) query = query.gte('tanggal_surat', `${year}-01-01`).lte('tanggal_surat', `${year}-12-31`); if (kategori) query = query.eq('kategori', kategori); if (startDate) query = query.gte('tanggal_surat', startDate); if (endDate) query = query.lte('tanggal_surat', endDate); const { data, error: downloadError } = await query; if (downloadError) { setError(isConnectionError(downloadError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Data tidak dapat diunduh'); setDownloadBusy(false); return; } const batch = (data ?? []) as unknown as Surat[]; active.push(...batch.filter((row) => (!month || String(Number(row.tanggal_surat.slice(5, 7))) === month) && `${row.nomor_surat} ${row.perihal}`.toLowerCase().includes(search.toLowerCase()))); if (batch.length < 1000) break; start += 1000; } if (!active.length) { toast('Tidak ada data untuk diunduh', 'info'); setDownloadBusy(false); return; } const sheetRows = active.map((row, index) => ({ No: safeExcelText(String(index + 1)), 'Nomor Surat': safeExcelText(row.nomor_surat), Tanggal: safeExcelText(shortDate(row.tanggal_surat)), Kategori: safeExcelText(kategoriLabel(row.kategori)), Perihal: safeExcelText(row.perihal) })); const sheet = XLSX.utils.json_to_sheet(sheetRows); sheet['!cols'] = [{ wch: 7 }, { wch: Math.max(16, ...sheetRows.map((row) => row['Nomor Surat'].length + 2)) }, { wch: 14 }, { wch: 14 }, { wch: Math.max(18, ...sheetRows.map((row) => row.Perihal.length + 2)) }]; const workbook = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(workbook, sheet, 'Rekap Surat'); const fileMonth = month ? months[Number(month) - 1] : ''; XLSX.writeFile(workbook, `rekap-surat-${fileMonth ? `${fileMonth}-` : ''}${year || 'semua'}.xlsx`); setDownloadBusy(false); toast('Rekap surat berhasil diunduh'); }
  async function changeStatus(row: Surat): Promise<void> { setStatusBusy(true); setError(''); const next = row.status === 'aktif' ? 'dibatalkan' : 'aktif'; const { error: updateError } = await supabase.from('surat').update({ status: next }).eq('id', row.id); setStatusBusy(false); if (updateError) setError(isConnectionError(updateError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Status surat tidak dapat diubah'); else { toast(next === 'aktif' ? 'Surat berhasil dipulihkan' : 'Surat berhasil dibatalkan'); setConfirming(null); await load(); } }
  function handleEditSaved(savedMessage: string): void { setEditing(null); toast(savedMessage); void load(); }
  const sortHeaders: { key: SortKey; label: string }[] = [{ key: 'nomor_surat', label: 'Nomor Surat' }, { key: 'tanggal_surat', label: 'Tanggal' }, { key: 'perihal', label: 'Perihal' }];
  return <><PageHeading title="Data & Rekap Surat" current="Data & Rekap Surat" />{error && <div className="mb-4"><ErrorNotice message={error} /></div>}<Card><div className="grid gap-4 xl:grid-cols-[1fr_180px_150px_auto] xl:items-end"><div><p className="mb-2 text-sm font-semibold">Pilih Periode</p><div className="grid gap-3 sm:grid-cols-2"><select value={draftMonth} onChange={(event) => setDraftMonth(event.target.value)} className="h-11 rounded-lg border border-[var(--line)] bg-white px-3 text-sm"><option value="">Semua Bulan</option>{months.map((monthName, index) => <option key={monthName} value={String(index + 1)}>{monthName}</option>)}</select><select value={draftYear} onChange={(event) => setDraftYear(event.target.value)} className="h-11 rounded-lg border border-[var(--line)] bg-white px-3 text-sm"><option value="">Semua Tahun</option>{years.map((item) => <option key={item} value={item}>{item}</option>)}</select></div></div><div className="hidden h-11 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white xl:flex xl:items-center xl:justify-center">Filter Aktif</div><label className="relative block"><Search size={17} className="absolute left-3 top-3 text-slate-400" /><input value={draftSearch} onChange={(event) => setDraftSearch(event.target.value)} placeholder="Cari langsung..." className="h-11 w-full rounded-lg border border-[var(--line)] bg-white pl-10 pr-3 text-sm outline-none focus:border-[var(--primary)]" /></label><button disabled={downloadBusy} onClick={() => void download()} className="flex h-11 items-center justify-center gap-2 rounded-lg border border-[var(--primary)] px-4 text-sm font-semibold text-[var(--primary)] hover:bg-[#e5f6f3] disabled:cursor-not-allowed disabled:opacity-60"><FileSpreadsheet size={17} />{downloadBusy ? 'Mengunduh...' : 'Download Excel'}</button></div><button onClick={() => setShowAdvanced((v) => !v)} className="mt-4 flex items-center gap-2 text-sm font-semibold text-[var(--primary)] hover:underline"><ChevronDown size={16} className={`transition-transform ${showAdvanced ? 'rotate-180' : ''}`} />Filter Lanjutan</button>{showAdvanced && <div className="animate-fade-in mt-4 grid gap-4 rounded-lg border border-[var(--line)] bg-[#f9fbfb] p-5 sm:grid-cols-3"><div><p className="mb-2 text-sm font-semibold">Kategori</p><select value={draftKategori} onChange={(event) => setDraftKategori(event.target.value)} className="h-11 w-full rounded-lg border border-[var(--line)] bg-white px-3 text-sm"><option value="">Semua Kategori</option>{categories.map((cat) => <option key={cat} value={cat}>{cat}</option>)}</select></div><div><p className="mb-2 text-sm font-semibold">Tanggal Mulai</p><input type="date" min={minimumDate()} value={draftStartDate} onChange={(event) => setDraftStartDate(event.target.value)} className="h-11 w-full rounded-lg border border-[var(--line)] bg-white px-3 text-sm outline-none focus:border-[var(--primary)]" /></div><div><p className="mb-2 text-sm font-semibold">Tanggal Akhir</p><input type="date" min={draftStartDate || minimumDate()} value={draftEndDate} onChange={(event) => setDraftEndDate(event.target.value)} className="h-11 w-full rounded-lg border border-[var(--line)] bg-white px-3 text-sm outline-none focus:border-[var(--primary)]" /></div></div>}<label className="mt-5 flex items-center gap-2 text-sm text-slate-600"><input type="checkbox" checked={cancelled} onChange={(event) => setCancelled(event.target.checked)} className="h-4 w-4 accent-[var(--primary)]" />Tampilkan surat yang dibatalkan</label><div className="mt-6 overflow-x-auto"><table className="w-full min-w-[1020px] text-left text-sm"><thead className="border-b border-[var(--line)] text-xs uppercase tracking-wide text-slate-400"><tr><th className="pb-3">No</th>{sortHeaders.map((h) => <th key={h.key} onClick={() => toggleSort(h.key)} className="cursor-pointer select-none pb-3 hover:text-[var(--primary)]"><span className="inline-flex items-center gap-1">{h.label}<SortIcon active={sortKey === h.key} dir={sortDir} /></span></th>)}<th className="pb-3">Kategori</th><th className="pb-3">Penginput</th><th className="pb-3">Aksi</th></tr></thead><tbody className="divide-y divide-[var(--line)]">{loading ? Array.from({ length: 5 }, (_, i) => <SkeletonDataRow key={i} />) : visible.map((row, index) => <tr key={row.id} onClick={() => setSelected(row)} className={`cursor-pointer transition hover:bg-slate-50 ${row.status === 'dibatalkan' ? 'text-slate-400' : ''}`}><td className="py-3.5">{(page - 1) * 10 + index + 1}</td><td className={`py-3.5 font-semibold ${row.status === 'dibatalkan' ? 'line-through' : ''}`}>{row.nomor_surat}</td><td className={`py-3.5 ${row.status === 'dibatalkan' ? 'line-through' : ''}`}>{shortDate(row.tanggal_surat)}</td><td className={`py-3.5 ${row.status === 'dibatalkan' ? 'line-through' : ''}`}>{row.perihal}</td><td className="py-3.5"><span className={`inline-block rounded-full px-2.5 py-1 text-[11px] font-semibold ${kategoriStyles[kategoriLabel(row.kategori)] ?? kategoriStyles['Lainnya']}`}>{kategoriLabel(row.kategori)}</span></td><td className="py-3.5">{row.profiles?.full_name || 'Tanpa nama'}</td><td className="py-3.5"><div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>{row.status === 'dibatalkan' && <span className="mr-1 rounded-full bg-slate-100 px-2 py-1 text-[11px] font-semibold">Dibatalkan</span>}<ActionButton label="Lihat" tone="blue" onClick={() => setSelected(row)}><Eye size={16} /></ActionButton>{row.status === 'aktif' ? <><ActionButton label="Edit" tone="orange" onClick={() => setEditing(row)}><Pencil size={16} /></ActionButton><ActionButton label="Batalkan" tone="red" onClick={() => setConfirming(row)}><Ban size={16} /></ActionButton></> : <ActionButton label="Pulihkan" tone="green" onClick={() => setConfirming(row)}><RotateCcw size={16} /></ActionButton>}</div></td></tr>)}</tbody></table>{!loading && !visible.length && <EmptyState title="Belum ada data surat" subtitle="Coba ubah filter periode atau masukkan surat baru" />}</div><div className="mt-5 flex flex-col gap-3 border-t border-[var(--line)] pt-4 text-sm text-slate-500 sm:flex-row sm:items-center sm:justify-between"><span>Menampilkan {filtered.length ? (page - 1) * 10 + 1 : 0} sampai {Math.min(page * 10, filtered.length)} dari {filtered.length} data</span><Pagination page={page} count={count} onChange={setPage} /></div></Card>{selected && <Dialog title="Detail Surat" onClose={() => setSelected(null)}><div className="space-y-4"><Detail label="Nomor Surat" value={selected.nomor_surat} /><Detail label="Tanggal" value={longDate(selected.tanggal_surat)} /><Detail label="Perihal" value={selected.perihal} /><Detail label="Kategori" value={kategoriLabel(selected.kategori)} /><Detail label="Penginput" value={selected.profiles?.full_name || 'Tanpa nama'} /><Detail label="Tanggal Input" value={dateTime(selected.created_at)} /><Detail label="Status" value={selected.status === 'aktif' ? 'Aktif' : 'Dibatalkan'} /></div></Dialog>}{editing && <Dialog title="Edit Surat" wide onClose={() => setEditing(null)}><SuratForm profile={profile} initial={{ nomor_surat: editing.nomor_surat, tanggal_surat: editing.tanggal_surat, perihal: editing.perihal, kategori: kategoriLabel(editing.kategori) }} editId={editing.id} onCancel={() => setEditing(null)} onSaved={(m) => handleEditSaved(m)} /></Dialog>}{confirming && <Dialog title={confirming.status === 'aktif' ? 'Batalkan Surat' : 'Pulihkan Surat'} onClose={() => { if (!statusBusy) setConfirming(null); }} dismissible={!statusBusy}><p className="text-sm leading-6 text-slate-600">{confirming.status === 'aktif' ? 'Apakah Anda yakin ingin membatalkan surat ini?' : 'Apakah Anda yakin ingin memulihkan surat ini?'}</p><div className="mt-7 flex justify-end gap-3"><button disabled={statusBusy} onClick={() => setConfirming(null)} className="h-10 rounded-lg border border-[var(--line)] px-5 text-sm font-semibold text-slate-600 disabled:opacity-60">Batal</button><button disabled={statusBusy} onClick={() => void changeStatus(confirming)} className="h-10 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white disabled:opacity-60">{statusBusy ? 'Menyimpan...' : confirming.status === 'aktif' ? 'Ya, Batalkan' : 'Ya, Pulihkan'}</button></div></Dialog>}</>;
}
function ActionButton({ children, label, tone, onClick }: { children: ReactNode; label: string; tone: string; onClick: () => void }): ReactNode { const styles: Record<string, string> = { blue: 'bg-[#e8f1fb] text-[#3975b5]', orange: 'bg-[#fff1df] text-[#c47c16]', red: 'bg-[#ffebeb] text-[#c74b4b]', green: 'bg-[#e4f6ed] text-[#3e9a66]' }; return <button title={label} aria-label={label} onClick={onClick} className={`rounded-lg p-2 ${styles[tone]} hover:brightness-95`}>{children}</button>; }

function ManageAccounts(): ReactNode {
  const [codes, setCodes] = useState<InviteCode[]>([]);
  const [profiles, setProfiles] = useState<Profile[]>([]);
  const [newCode, setNewCode] = useState('');
  const [error, setError] = useState('');
  const [temp, setTemp] = useState('');
  const [tempName, setTempName] = useState('');
  const [busy, setBusy] = useState('');
  const toast = useToast();
  async function load(): Promise<void> { const [{ data: codeData, error: codeError }, { data: profileData, error: profileError }] = await Promise.all([supabase.from('invite_codes').select('id, code, created_at, expires_at, used_at, used_by').order('created_at', { ascending: false }), supabase.from('profiles').select('id, full_name, email, role, must_change_password, avatar_path').order('full_name')]); if (codeError || profileError) setError(isConnectionError(codeError ?? profileError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Data akun tidak dapat dimuat'); else { setCodes(codeData ?? []); setProfiles(profileData ?? []); } }
  useEffect(() => { void load(); }, []);
  async function create(): Promise<void> { setBusy('create'); setError(''); const { data, error: createError } = await supabase.rpc('create_invite_code'); setBusy(''); if (createError || !data) { setError(isConnectionError(createError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Token tidak dapat dibuat'); return; } setNewCode(data); toast('Token baru berhasil dibuat'); await load(); }
  async function remove(id: string): Promise<void> { setBusy(`remove-${id}`); setError(''); const { error: removeError } = await supabase.from('invite_codes').delete().eq('id', id); setBusy(''); if (removeError) setError(isConnectionError(removeError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Token tidak dapat dihapus'); else { toast('Token berhasil dihapus'); await load(); } }
  async function reset(user: Profile): Promise<void> { if (!window.confirm(`Reset password untuk ${user.full_name || user.email}?`)) return; setBusy(`reset-${user.id}`); setError(''); const { data, error: resetError } = await supabase.functions.invoke('reset-admin-password', { body: { user_id: user.id } }); setBusy(''); if (resetError || !data?.temporary_password) setError(isConnectionError(resetError) ? 'Koneksi bermasalah, silakan coba lagi' : data?.error ?? 'Password tidak dapat direset'); else { setTemp(data.temporary_password); setTempName(user.full_name || user.email); toast('Password berhasil direset'); await load(); } }
  const status = (code: InviteCode): string => code.used_at ? 'Terpakai' : new Date(code.expires_at).getTime() <= Date.now() ? 'Kedaluwarsa' : 'Aktif';
  return <><PageHeading title="Kelola Akun" current="Kelola Akun" />{error && <div className="mb-4"><ErrorNotice message={error} /></div>}<div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><Card><div className="flex items-start justify-between"><div><h2 className="text-lg font-bold">Token pendaftaran</h2><p className="mt-1 text-sm text-slate-400">Berlaku selama 7 hari.</p></div><ShieldCheck className="text-[var(--primary)]" /></div><button disabled={busy === 'create'} onClick={() => void create()} className="mt-5 h-10 rounded-lg bg-[var(--primary)] px-4 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60">{busy === 'create' ? 'Membuat...' : 'Buat Token'}</button>{newCode && <div className="animate-scale-in mt-4 rounded-xl bg-[#e5f6f3] p-4"><p className="text-xs font-semibold text-[var(--primary)]">Token baru</p><div className="mt-1 flex items-center justify-between"><strong className="text-xl tracking-widest">{newCode}</strong><CopyButton text={newCode} onCopied={() => toast('Token disalin')} className="rounded p-2 text-[var(--primary)]" /></div></div>}<div className="mt-6 overflow-x-auto"><table className="w-full min-w-[430px] text-left text-sm"><thead className="border-b border-[var(--line)] text-xs text-slate-400"><tr><th className="pb-2">Kode</th><th className="pb-2">Kedaluwarsa</th><th className="pb-2">Status</th><th /></tr></thead><tbody className="divide-y divide-[var(--line)]">{codes.map((code) => <tr key={code.id}><td className="py-3 font-semibold">{code.code}</td><td className="py-3 text-slate-500">{new Date(code.expires_at).toLocaleDateString('id-ID')}</td><td className="py-3 text-xs">{status(code)}</td><td className="py-3 text-right">{status(code) === 'Aktif' && <button disabled={busy === `remove-${code.id}`} onClick={() => void remove(code.id)} className="text-slate-400 hover:text-red-600 disabled:opacity-50" aria-label="Hapus token">{busy === `remove-${code.id}` ? '...' : <Trash2 size={15} />}</button>}</td></tr>)}</tbody></table></div></Card><Card><h2 className="text-lg font-bold">Daftar akun</h2><p className="mt-1 text-sm text-slate-400">Reset password hanya untuk Admin.</p><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[540px] text-left text-sm"><thead className="border-b border-[var(--line)] text-xs text-slate-400"><tr><th className="pb-2">Nama</th><th className="pb-2">Email</th><th className="pb-2">Peran</th><th /></tr></thead><tbody className="divide-y divide-[var(--line)]">{profiles.map((user) => <tr key={user.id}><td className="py-3 font-semibold">{user.full_name || 'Tanpa nama'}</td><td className="py-3 text-slate-500">{user.email}</td><td className="py-3 text-xs">{user.role === 'super_admin' ? 'Super Admin' : 'Admin'}</td><td className="py-3 text-right">{user.role === 'admin' && <button disabled={busy === `reset-${user.id}`} onClick={() => void reset(user)} className="text-xs font-semibold text-[var(--primary)] hover:underline disabled:opacity-50">{busy === `reset-${user.id}` ? 'Memproses...' : 'Reset Password'}</button>}</td></tr>)}</tbody></table></div></Card></div>{temp && <Dialog title="Password sementara" onClose={() => setTemp('')}><p className="text-sm text-slate-500">Untuk {tempName}</p><div className="mt-4 flex items-center justify-between rounded-lg bg-slate-100 p-3"><strong className="font-mono text-lg tracking-widest">{temp}</strong><CopyButton text={temp} onCopied={() => toast('Password disalin')} className="rounded p-2 text-[var(--primary)]" /></div><p className="mt-4 text-sm leading-6 text-amber-700">Password ini hanya tampil sekali. Sampaikan ke pemiliknya dan minta segera diganti.</p><button onClick={() => setTemp('')} className="mt-5 h-10 w-full rounded-lg bg-[var(--primary)] text-sm font-semibold text-white">Tutup</button></Dialog>}</>;
}

function AccountPage({ profile, onAvatarChange }: { profile: Profile; onAvatarChange: (path: string | null) => void }): ReactNode {
  const [oldPassword, setOldPassword] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [confirmation, setConfirmation] = useState('');
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [avatarPath, setAvatarPath] = useState<string | null>(profile.avatar_path);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [previewFile, setPreviewFile] = useState<File | null>(null);
  const [uploadBusy, setUploadBusy] = useState(false);
  const [deleteBusy, setDeleteBusy] = useState(false);
  const [avatarError, setAvatarError] = useState('');
  const toast = useToast();
  const fileRef = useRef<HTMLInputElement>(null);
  async function submit(event: FormEvent): Promise<void> {
    event.preventDefault(); setError('');
    if (!oldPassword || !newPassword || !confirmation) { setError('Semua kolom wajib diisi'); return; }
    if (newPassword.length < 8) { setError('Password minimal 8 karakter'); return; }
    if (newPassword !== confirmation) { setError('Konfirmasi password baru tidak sama'); return; }
    if (oldPassword === newPassword) { setError('Password baru tidak boleh sama dengan password lama'); return; }
    setBusy(true);
    const { error: verifyError } = await supabase.auth.signInWithPassword({ email: profile.email, password: oldPassword });
    if (verifyError) { setBusy(false); setError(isConnectionError(verifyError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Password lama salah'); return; }
    const { error: updateError } = await supabase.auth.updateUser({ password: newPassword });
    setBusy(false);
    if (updateError) { const messageText = updateError.message.toLowerCase(); setError(isConnectionError(updateError) ? 'Koneksi bermasalah, silakan coba lagi' : messageText.includes('weak') || (messageText.includes('password') && messageText.includes('strength')) ? 'Password terlalu lemah, gunakan kombinasi huruf, angka, dan simbol' : 'Gagal mengganti password, coba lagi'); return; }
    setOldPassword(''); setNewPassword(''); setConfirmation('');
    toast('Password berhasil diganti');
  }
  function pickPhoto(event: ChangeEvent<HTMLInputElement>): void { const file = event.target.files?.[0]; if (!file) return; const validTypes = ['image/jpeg', 'image/png', 'image/webp']; if (!validTypes.includes(file.type)) { setAvatarError('Format foto harus JPG, PNG, atau WebP'); return; } if (file.size > 5242880) { setAvatarError('Ukuran foto maksimal 5 MB'); return; } setAvatarError(''); setPreviewUrl(URL.createObjectURL(file)); setPreviewFile(file); }
  function cancelPreview(): void { if (previewUrl) URL.revokeObjectURL(previewUrl); setPreviewUrl(null); setPreviewFile(null); if (fileRef.current) fileRef.current.value = ''; }
  async function savePhoto(): Promise<void> { if (!previewFile) return; setUploadBusy(true); setAvatarError(''); try { const blob = await processImageFile(previewFile); const oldPath = avatarPath; const newPath = `${profile.id}/avatar-${Date.now()}.jpg`; const { error: uploadError } = await supabase.storage.from('avatars').upload(newPath, blob, { contentType: 'image/jpeg' }); if (uploadError) { setAvatarError(isConnectionError(uploadError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Gagal mengunggah foto, coba lagi'); setUploadBusy(false); return; } const { error: rpcError } = await supabase.rpc('set_my_avatar', { p_path: newPath }); if (rpcError) { setAvatarError('Gagal mengunggah foto, coba lagi'); setUploadBusy(false); return; } if (oldPath) { await supabase.storage.from('avatars').remove([oldPath]); } setAvatarPath(newPath); onAvatarChange(newPath); toast('Foto profil berhasil diperbarui'); cancelPreview(); } catch { setAvatarError('Gagal mengunggah foto, coba lagi'); } setUploadBusy(false); }
  async function deletePhoto(): Promise<void> { if (!window.confirm('Hapus foto profil?')) return; setDeleteBusy(true); setAvatarError(''); const path = avatarPath; const { error: rpcError } = await supabase.rpc('set_my_avatar', { p_path: null }); if (rpcError) { setAvatarError('Gagal menghapus foto, coba lagi'); setDeleteBusy(false); return; } if (path) { await supabase.storage.from('avatars').remove([path]); } setAvatarPath(null); onAvatarChange(null); toast('Foto profil berhasil dihapus'); setDeleteBusy(false); }
  return <><PageHeading title="Profil Saya" current="Profil Saya" /><div className="grid gap-5 lg:grid-cols-[.85fr_1.15fr]"><div className="space-y-5"><Card><div className="flex items-center gap-3"><Camera size={22} className="text-[var(--primary)]" /><div><h2 className="text-lg font-bold text-[var(--ink)]">Foto Profil</h2><p className="mt-1 text-sm text-slate-400">JPG, PNG, atau WebP. Maksimal 5 MB.</p></div></div><div className="mt-6 flex flex-col items-center"><div className="h-28 w-28 overflow-hidden rounded-full">{previewUrl ? <img src={previewUrl} alt="Pratinjau" className="h-full w-full object-cover" /> : <Avatar name={profile.full_name || profile.email} path={avatarPath} className="h-28 w-28 text-3xl" />}</div>{avatarError && <div className="mt-4 w-full"><ErrorNotice message={avatarError} /></div>}{previewUrl ? <div className="mt-5 flex gap-3"><button disabled={uploadBusy} onClick={() => void savePhoto()} className="h-10 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60">{uploadBusy ? 'Mengunggah...' : 'Simpan Foto'}</button><button disabled={uploadBusy} onClick={cancelPreview} className="h-10 rounded-lg border border-[var(--line)] px-5 text-sm font-semibold text-slate-600 disabled:opacity-60">Batal</button></div> : <div className="mt-5 flex gap-3"><button disabled={uploadBusy || deleteBusy} onClick={() => fileRef.current?.click()} className="h-10 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-60">Pilih Foto</button>{avatarPath && <button disabled={uploadBusy || deleteBusy} onClick={() => void deletePhoto()} className="h-10 rounded-lg border border-red-200 px-5 text-sm font-semibold text-red-600 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-60">{deleteBusy ? 'Menghapus...' : 'Hapus Foto'}</button>}</div>}<input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => pickPhoto(event)} className="hidden" /></div></Card><Card><div className="flex items-center gap-4"><Avatar name={profile.full_name || profile.email} path={avatarPath} className="h-14 w-14 text-lg" /><div><h2 className="text-lg font-bold text-[var(--ink)]">Informasi Akun</h2><p className="mt-1 text-sm text-slate-400">Data akun Anda</p></div></div><dl className="mt-7 space-y-5"><div><dt className="text-xs font-semibold uppercase tracking-wide text-slate-400">Nama</dt><dd className="mt-1 text-sm font-semibold text-[var(--ink)]">{profile.full_name || 'Belum diisi'}</dd></div><div><dt className="text-xs font-semibold uppercase tracking-wide text-slate-400">Email</dt><dd className="mt-1 text-sm font-semibold text-[var(--ink)]">{profile.email}</dd></div><div><dt className="text-xs font-semibold uppercase tracking-wide text-slate-400">Peran</dt><dd className="mt-1 text-sm font-semibold text-[var(--ink)]">{profile.role === 'super_admin' ? 'Super Admin' : 'Admin'}</dd></div></dl></Card></div><Card><div className="mb-6"><h2 className="text-lg font-bold text-[var(--ink)]">Ganti Password</h2><p className="mt-1 text-sm text-slate-400">Masukkan password lama untuk memastikan perubahan ini.</p></div>{error && <div className="mb-4"><ErrorNotice message={error} /></div>}<form onSubmit={(event) => void submit(event)} className="space-y-4"><PasswordField label="Password Lama" value={oldPassword} onChange={setOldPassword} autoComplete="current-password" /><PasswordField label="Password Baru" value={newPassword} onChange={setNewPassword} autoComplete="new-password" /><PasswordField label="Konfirmasi Password Baru" value={confirmation} onChange={setConfirmation} autoComplete="new-password" /><button disabled={busy} className="h-11 w-full rounded-lg bg-[var(--primary)] text-sm font-semibold text-white hover:bg-[var(--primary-dark)] disabled:cursor-not-allowed disabled:opacity-60">{busy ? 'Menyimpan...' : 'Simpan Password'}</button></form></Card></div></>;
}

function NotFound(): ReactNode { return <div className="flex min-h-[60vh] items-center justify-center"><Card className="max-w-md text-center"><h1 className="text-xl font-bold text-[var(--ink)]">Halaman tidak ditemukan</h1><p className="mt-2 text-sm text-slate-500">Halaman yang Anda cari tidak tersedia.</p><button onClick={() => goTo('/')} className="mt-5 h-11 rounded-lg bg-[var(--primary)] px-5 text-sm font-semibold text-white">Kembali ke Dashboard</button></Card></div>; }

function Sidebar({ page, profile, open, onClose, onNavigate, onLogout }: { page: Page; profile: Profile; open: boolean; onClose: () => void; onNavigate: (page: Page) => void; onLogout: () => Promise<void> }): ReactNode { const items = profile.role === 'super_admin' ? [...navItems, { id: 'manage' as Page, label: 'Kelola Akun', icon: UserRoundCog }] : navItems; return <><div onClick={onClose} className={`fixed inset-0 z-20 bg-slate-900/40 transition lg:hidden ${open ? 'visible opacity-100' : 'invisible opacity-0'}`} /><aside className={`fixed inset-y-0 left-0 z-30 flex w-60 flex-col bg-[var(--sidebar)] px-4 py-5 transition-transform lg:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}><div className="px-2"><Brand sidebar /></div><p className="mt-10 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-white/35">Menu utama</p><nav className="mt-3 space-y-1">{items.map((item) => { const Icon = item.icon; return <button key={item.id} onClick={() => onNavigate(item.id)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-semibold transition-colors ${page === item.id ? 'bg-[#0e7c7b] text-white' : 'text-white/65 hover:bg-white/10 hover:text-white'}`}><Icon size={18} />{item.label}</button>; })}</nav><button onClick={() => void onLogout()} className="mt-auto flex items-center gap-3 rounded-lg px-3 py-3 text-left text-sm font-semibold text-white/65 transition-colors hover:bg-red-500/20 hover:text-white"><LogOut size={18} />Keluar</button></aside></>; }
function Topbar({ profile, onMenu, onNavigate, onLogout }: { profile: Profile; onMenu: () => void; onNavigate: (page: Page) => void; onLogout: () => Promise<void> }): ReactNode {
  const [show, setShow] = useState(false);
  const name = profile.full_name || profile.email;
  const closeMenu = useCallback((): void => setShow(false), []);
  const ref = useClickOutside<HTMLDivElement>(closeMenu);
  useEffect(() => {
    function onKey(event: KeyboardEvent): void { if (event.key === 'Escape') setShow(false); }
    document.addEventListener('keydown', onKey);
    return (): void => document.removeEventListener('keydown', onKey);
  }, []);
  return <header className="sticky top-0 z-10 flex h-[72px] items-center justify-between border-b border-[var(--line)] bg-white px-5 sm:px-8"><button onClick={onMenu} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100 lg:hidden" aria-label="Buka menu"><Menu size={21} /></button><div ref={ref} className="relative ml-auto"><button onClick={() => setShow((current) => !current)} className="flex items-center gap-3 rounded-lg p-1.5 hover:bg-slate-50" aria-expanded={show}><Avatar name={name} path={profile.avatar_path} className="h-9 w-9 text-xs" /><span className="hidden text-left sm:block"><span className="block text-sm font-semibold text-[var(--ink)]">{name}</span><span className="block text-xs text-slate-400">{profile.role === 'super_admin' ? 'Super Admin' : 'Admin'}</span></span><ChevronDown size={16} className="text-slate-400" /></button>{show && <div className="animate-fade-in absolute right-0 top-12 w-40 rounded-lg border border-[var(--line)] bg-white p-1 shadow-lg"><button onClick={() => { setShow(false); onNavigate('account'); }} className="flex w-full items-center rounded-md px-3 py-2 text-left text-sm text-slate-700 hover:bg-slate-50">Profil Saya</button><button onClick={() => void onLogout()} className="flex w-full items-center gap-2 rounded-md px-3 py-2 text-left text-sm text-red-600 hover:bg-red-50"><LogOut size={15} />Keluar</button></div>}</div></header>;
}
function Shell({ profile, path, onLogout, onAvatarChange }: { profile: Profile; path: string; onLogout: () => Promise<void>; onAvatarChange: (path: string | null) => void }): ReactNode { const [open, setOpen] = useState(false); const page: Page = path === '/input-surat' ? 'input' : path === '/data-surat' ? 'data' : path === '/kelola-akun' ? 'manage' : path === '/akun' ? 'account' : 'dashboard'; function navigate(next: Page): void { goTo(next === 'input' ? '/input-surat' : next === 'data' ? '/data-surat' : next === 'manage' ? '/kelola-akun' : next === 'account' ? '/akun' : '/'); setOpen(false); } const knownPath = ['/', '/input-surat', '/data-surat', '/kelola-akun', '/akun'].includes(path); return <div className="min-h-screen bg-[var(--page)]"><Sidebar page={page} profile={profile} open={open} onClose={() => setOpen(false)} onNavigate={navigate} onLogout={onLogout} /><div className="lg:pl-60"><Topbar profile={profile} onMenu={() => setOpen(true)} onNavigate={navigate} onLogout={onLogout} /><main className="mx-auto max-w-[1380px] px-5 py-7 sm:px-8">{!knownPath && <NotFound />}{knownPath && page === 'dashboard' && <div key="dashboard" className="animate-fade-up"><Dashboard profile={profile} onGoData={() => navigate('data')} onGoInput={() => navigate('input')} /></div>}{knownPath && page === 'input' && <div key="input" className="animate-fade-up"><InputPage profile={profile} onGoData={() => navigate('data')} /></div>}{knownPath && page === 'data' && <div key="data" className="animate-fade-up"><DataPage profile={profile} /></div>}{knownPath && page === 'manage' && profile.role === 'super_admin' && <div key="manage" className="animate-fade-up"><ManageAccounts /></div>}{knownPath && page === 'account' && <div key="account" className="animate-fade-up"><AccountPage profile={profile} onAvatarChange={onAvatarChange} /></div>}</main></div></div>; }

function App(): ReactNode { const [session, setSession] = useState<Session | null>(null); const [profile, setProfile] = useState<Profile | null>(null); const [loading, setLoading] = useState(true); const [path, setPath] = useState(window.location.pathname); const [sessionMessage, setSessionMessage] = useState(''); async function loadProfile(next: Session): Promise<void> { const { data, error } = await supabase.from('profiles').select('id, full_name, email, role, must_change_password, avatar_path').eq('id', next.user.id).maybeSingle(); if (error) throw error; setProfile(data); } function updateAvatarPath(avatarPath: string | null): void { setProfile((current) => current ? { ...current, avatar_path: avatarPath } : current); } useEffect(() => { const pop = (): void => setPath(window.location.pathname); window.addEventListener('popstate', pop); let mounted = true; supabase.auth.getSession().then(async ({ data, error }) => { if (!mounted) return; if (error) { setSessionMessage(isConnectionError(error) ? 'Koneksi bermasalah, silakan coba lagi' : 'Sesi Anda berakhir, silakan login kembali'); setLoading(false); return; } setSession(data.session); if (data.session) { try { await loadProfile(data.session); } catch (profileError) { setSessionMessage(isConnectionError(profileError) ? 'Koneksi bermasalah, silakan coba lagi' : 'Sesi Anda berakhir, silakan login kembali'); } } if (mounted) setLoading(false); }).catch(() => { if (mounted) { setSessionMessage('Koneksi bermasalah, silakan coba lagi'); setLoading(false); } }); const { data: listener } = supabase.auth.onAuthStateChange((event, next) => { if (!mounted) return; if (!next && event !== 'INITIAL_SESSION') { setSessionMessage('Sesi Anda berakhir, silakan login kembali'); setProfile(null); } setSession(next); if (!next && event === 'SIGNED_OUT') setProfile(null); }); return () => { mounted = false; window.removeEventListener('popstate', pop); listener.subscription.unsubscribe(); }; }, []); async function login(next: Session): Promise<void> { setSessionMessage(''); setSession(next); await loadProfile(next); } async function logout(): Promise<void> { await supabase.auth.signOut(); setSession(null); setProfile(null); goTo('/'); } if (loading) return <div className="flex min-h-screen items-center justify-center bg-[var(--page)] text-sm font-semibold text-[var(--primary)]">Memuat...</div>; if (!session) return <><ToastHost />{path === '/daftar' ? <RegisterPage /> : path === '/' ? <LoginPage onLogin={login} sessionMessage={sessionMessage} /> : <NotFound />}</>; if (!profile) return <div className="flex min-h-screen items-center justify-center bg-[var(--page)] px-5 text-center text-sm text-slate-500"><div>Koneksi bermasalah, silakan coba lagi</div></div>; if (profile.must_change_password) return <><ToastHost /><ChangePasswordPage onComplete={async () => { await loadProfile(session); goTo('/'); }} /></>; if (path === '/kelola-akun' && profile.role !== 'super_admin') { goTo('/'); return null; } return <><ToastHost /><Shell profile={profile} path={path} onLogout={logout} onAvatarChange={updateAvatarPath} /></>; }

export default function AppWithBoundary(): ReactNode { return <AppErrorBoundary><App /></AppErrorBoundary>; }